// VUE-01 Vite 脚手架、SFC 与项目结构
// 首考题 3 原文：按中文讲义“建立可复现的练习工程”和“固定入口练习与单变量排错”实现无 Router 的双资料卡片项目。固定输入为两张卡片 25/30 分钟、@/ReadingCard.vue、VITE_API_BASE=/api、提示开关 false；提交全部源码、项目树、dev/typecheck/build/preview 日志和产物清单；断言第一张展开不影响第二张、公开配置显示 /api 与 false、卡片 scoped 标题不命中外部 h2
// 首考题 4 原文：分别注入并恢复正文表格四项故障：只删除 Vite 别名、删除公开地址变量、删除 scoped、mount 改为 #missing；每项提交失败证据、可证伪假设、最小修复和回归
// 把题目给定的具体 fixture 写入 fixedInput；不要把预期替换成通用 PASS/CONTROLLED。
const fixedInput = Object.freeze({ /* 填写首考题 3 的固定输入 */ });
const expected = Object.freeze({ /* 填写题目要求的具体预期 */ });

function solve(input) {
  // 根据学习资料实现首考题 3。
  throw new Error('TODO');
}

let actual;
try {
  actual = solve(fixedInput);
  console.log({ fixedInput, expected, actual });
  console.assert(JSON.stringify(actual) === JSON.stringify(expected), '实际输出与首考题 3 的具体预期不一致');
} catch (error) {
  console.error({ fixedInput, expected, error: String(error) });
  throw error;
}

